using System;using System.IO;using System.Reflection;
class GeneratorExport{static void Main(string[] args){var a=Assembly.LoadFile(Path.GetFullPath(args[0]));var t=a.GetType("SituationalPractice.NativeRuntime",true);Directory.CreateDirectory(args[1]);foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.Static)){var p=m.GetParameters();if(m.Name.StartsWith("Build")&&m.ReturnType==typeof(byte[])&&p.Length==2&&p[0].ParameterType==typeof(long)&&p[1].ParameterType==typeof(long))File.WriteAllBytes(Path.Combine(args[1],m.Name+".bin"),(byte[])m.Invoke(null,new object[]{0x140000000L,0x200000000L}));}var gate=t.GetMethod("BuildGate");for(int i=0;i<3;i++)File.WriteAllBytes(Path.Combine(args[1],"BuildGate"+i+".bin"),(byte[])gate.Invoke(null,new object[]{0x140000000L,0x200000000L,i}));}}
